/**
 * Tab 3 — Thống kê đánh giá mức độ tổn thương (Phụ lục IV b)
 *
 * Charts (parity bd-3):
 *  • Doughnut — Đánh giá diễn tiến tình huống (A–I)
 *  • Doughnut — Mức độ tổn thương sức khỏe (NC0–NC3)
 *  • Bar      — Đánh giá tổn thương tổ chức
 */
import React, { useCallback, useState } from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import type { ChartEvent, ActiveElement } from 'chart.js';
import { Doughnut, Bar } from 'react-chartjs-2';
import { MedicalIncidentReport, ChartDataItem, MedicalIncidentReportFilters } from '../../../models/MedicalIncident';
import {
  CHART_COLORS,
  DOUGHNUT_OPTIONS,
  BAR_OPTIONS_VERTICAL,
  buildBaseDateListUrl,
} from '../chartUtils';
import { ChartViewListPopover, ChartPopoverState } from './ChartViewListPopover';
import s from './shared.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

interface Props {
  report: MedicalIncidentReport;
  filters: MedicalIncidentReportFilters;
}

const ClickHint: React.FC = () => (
  <span
    title="Nhấn vào cột/phần để xem danh sách"
    style={{ marginLeft: 6, fontSize: '0.7rem', color: '#94a3b8', fontWeight: 400, cursor: 'default' }}
  >
    <i className="fas fa-hand-pointer" />
  </span>
);

const ChartEmpty: React.FC<{ message?: string }> = ({
  message = 'Chưa có đánh giá tổn thương trong kỳ (Tab 4B)',
}) => (
  <div className={s.emptyState}>
    <i className="fas fa-notes-medical" />
    {message}
  </div>
);

const hasData = (items: ChartDataItem[]) => items.some((d) => d.count > 0);

const toDoughnutData = (items: ChartDataItem[], colors?: string[]) => ({
  labels: items.map((d) => d.label),
  datasets: [
    {
      data: items.map((d) => d.count),
      backgroundColor: colors ?? CHART_COLORS.slice(0, Math.max(items.length, 1)),
      borderWidth: 2,
      borderColor: '#fff',
    },
  ],
});

export const Tab3Assessment: React.FC<Props> = ({ report, filters }) => {
  const [popover, setPopover] = useState<ChartPopoverState | null>(null);
  const closePopover = useCallback(() => setPopover(null), []);

  const makeClickHandler = (
    items: ChartDataItem[],
    hintBuilder: (item: ChartDataItem) => string,
  ) => (chartEvent: ChartEvent, elements: ActiveElement[]) => {
    if (!elements.length) { setPopover(null); return; }
    const idx  = elements[0].index;
    const item = items[idx];
    if (!item || item.count === 0) { setPopover(null); return; }
    const native = chartEvent.native as MouseEvent;
    setPopover({
      x:          native.clientX,
      y:          native.clientY,
      label:      item.label,
      filterHint: hintBuilder(item),
      listUrl:    buildBaseDateListUrl(filters),
    });
  };

  const progress  = report.bySituationProgress ?? [];
  const injuryNc  = report.byInjuryNc ?? [];
  const orgInjury = report.byOrgInjury ?? [];

  const doughnutOptLegendRight = {
    ...DOUGHNUT_OPTIONS,
    plugins: {
      ...DOUGHNUT_OPTIONS.plugins,
      legend: {
        position: 'right' as const,
        labels: { font: { size: 10 }, padding: 6, boxWidth: 10 },
      },
    },
  };

  const orgBarData = {
    labels: orgInjury.map((d) => d.label),
    datasets: [
      {
        label: 'Số sự cố',
        data: orgInjury.map((d) => d.count),
        backgroundColor: CHART_COLORS.slice(0, Math.max(orgInjury.length, 1)),
        borderRadius: 4,
        borderSkipped: false as const,
      },
    ],
  };

  return (
    <div>
      {popover && <ChartViewListPopover {...popover} onClose={closePopover} />}

      <div className={s.sectionBanner}>
        <p className={s.sectionBannerTitle}>Đánh giá mức độ tổn thương</p>
        <p className={s.sectionBannerSub}>Theo Phụ lục IV b, Thông tư 43/2018/TT-BYT</p>
      </div>

      <div className={s.grid2} style={{ marginBottom: 16 }}>
        <div className={s.chartCard}>
          <h3>
            <span className={s.figNum}>Hình 1.</span>
            Đánh giá diễn tiến tình huống
            <ClickHint />
          </h3>
          <div className={`${s.chartBody} ${s.chartBodyLarge}`}>
            {hasData(progress) ? (
              <Doughnut
                data={toDoughnutData(progress)}
                options={{
                  ...doughnutOptLegendRight,
                  onClick: makeClickHandler(progress, (item) => `Diễn tiến: ${item.label} — ${item.count} sự cố`),
                }}
              />
            ) : (
              <ChartEmpty />
            )}
          </div>
        </div>
        <div className={s.chartCard}>
          <h3>
            <span className={s.figNum}>Hình 2.</span>
            Đánh giá mức độ tổn thương sức khỏe
            <ClickHint />
          </h3>
          <div className={`${s.chartBody} ${s.chartBodyLarge}`}>
            {hasData(injuryNc) ? (
              <Doughnut
                data={toDoughnutData(injuryNc, ['#f59e0b', '#3b82f6', '#8b5cf6', '#ef4444'])}
                options={{
                  ...doughnutOptLegendRight,
                  onClick: makeClickHandler(injuryNc, (item) => `Mức độ tổn thương: ${item.label} — ${item.count} sự cố`),
                }}
              />
            ) : (
              <ChartEmpty />
            )}
          </div>
        </div>
      </div>

      <div className={s.chartCard}>
        <h3>
          <span className={s.figNum}>Hình 3.</span>
          Đánh giá tổn thương tổ chức
          <ClickHint />
        </h3>
        <div className={`${s.chartBody} ${s.chartBodyLarge}`}>
          {hasData(orgInjury) ? (
            <Bar
              data={orgBarData}
              options={{
                ...BAR_OPTIONS_VERTICAL,
                onClick: makeClickHandler(orgInjury, (item) => `Tổn thương tổ chức: ${item.label} — ${item.count} sự cố`),
              }}
            />
          ) : (
            <ChartEmpty />
          )}
        </div>
      </div>
    </div>
  );
};
