/**
 * Tab 1 — Thống kê SCYK được báo cáo
 *
 * Charts:
 *  • Bar chart   — Số sự cố theo tháng
 *  • Doughnut — byReportType, byReportingDepartment (Khoa báo cáo — SSOT mọi báo cáo),
 *               byOccurrenceStatus, bySeverity
 *  • H-Bar       — byAffectedSubject
 *
 * Clicking any bar/segment opens a popover with a "Xem danh sách" link.
 * Charts with a direct list filter (month → date range, severity, reportType)
 * navigate with that specific filter applied.
 */
import React, { useCallback, useState } from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import type { ChartEvent, ActiveElement } from 'chart.js';
import { Bar, Doughnut } from 'react-chartjs-2';
import { MedicalIncidentReport, ChartDataItem, MedicalIncidentReportFilters } from '../../../models/MedicalIncident';
import {
  CHART_COLORS,
  DOUGHNUT_OPTIONS,
  BAR_OPTIONS_VERTICAL,
  BAR_OPTIONS_HORIZONTAL,
  buildMonthListUrl,
  buildSeverityListUrl,
  buildReportTypeListUrl,
  buildBaseDateListUrl,
} from '../chartUtils';
import { ChartViewListPopover, ChartPopoverState } from './ChartViewListPopover';
import s from './shared.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

interface Props {
  report: MedicalIncidentReport;
  filters: MedicalIncidentReportFilters;
}

const toDoughnutData = (items: ChartDataItem[]) => ({
  labels: items.map((d) => d.label),
  datasets: [
    {
      data: items.map((d) => d.count),
      backgroundColor: CHART_COLORS.slice(0, items.length),
      borderWidth: 2,
      borderColor: '#fff',
    },
  ],
});

/** Small icon hint shown in chart headings to signal click interactivity. */
const ClickHint: React.FC = () => (
  <span
    title="Nhấn vào cột/phần để xem danh sách"
    style={{ marginLeft: 6, fontSize: '0.7rem', color: '#94a3b8', fontWeight: 400, cursor: 'default' }}
  >
    <i className="fas fa-hand-pointer" />
  </span>
);

export const Tab1ReportedStats: React.FC<Props> = ({ report, filters }) => {
  const [popover, setPopover] = useState<ChartPopoverState | null>(null);
  const closePopover = useCallback(() => setPopover(null), []);

  /** Generic click handler factory for both Bar and Doughnut charts. */
  const makeClickHandler = (
    items: ChartDataItem[],
    urlBuilder:  (item: ChartDataItem) => string,
    hintBuilder: (item: ChartDataItem) => string,
  ) => (chartEvent: ChartEvent, elements: ActiveElement[]) => {
    if (!elements.length) { setPopover(null); return; }
    const idx  = elements[0].index;
    const item = items[idx];
    if (!item || item.count === 0) { setPopover(null); return; }
    const native = chartEvent.native as MouseEvent;
    setPopover({
      x:          native.clientX,
      y:          native.clientY,
      label:      item.label,
      filterHint: hintBuilder(item),
      listUrl:    urlBuilder(item),
    });
  };

  // ── Bar: by month ────────────────────────────────────────────────────────
  const monthBarData = {
    labels: report.byMonth.map((d) => d.label),
    datasets: [
      {
        label: 'Số sự cố',
        data: report.byMonth.map((d) => d.count),
        backgroundColor: '#0ea5e9',
        borderRadius: 5,
        borderSkipped: false,
      },
    ],
  };

  const monthOptions = {
    ...BAR_OPTIONS_VERTICAL,
    onClick: makeClickHandler(
      report.byMonth,
      (item) => buildMonthListUrl(item.key, filters),
      (item) => `Lọc theo tháng ${item.key} — ${item.count} sự cố`,
    ),
  };

  // ── Horizontal bar: by affected subject ──────────────────────────────────
  const subjectBarData = {
    labels: report.byAffectedSubject.map((d) => d.label),
    datasets: [
      {
        label: 'Số lượng',
        data: report.byAffectedSubject.map((d) => d.count),
        backgroundColor: CHART_COLORS.slice(0, report.byAffectedSubject.length),
        borderRadius: 4,
      },
    ],
  };

  const subjectOptions = {
    ...BAR_OPTIONS_HORIZONTAL,
    onClick: makeClickHandler(
      report.byAffectedSubject,
      () => buildBaseDateListUrl(filters),
      (item) => `${item.label} — xem danh sách trong khoảng thời gian đã chọn`,
    ),
  };

  // ── Doughnut click options ────────────────────────────────────────────────

  const reportTypeOptions = {
    ...DOUGHNUT_OPTIONS,
    onClick: makeClickHandler(
      report.byReportType,
      (item) => buildReportTypeListUrl(item.key, filters),
      (item) => `Lọc hình thức: ${item.label} — ${item.count} sự cố`,
    ),
  };

  const reportingDeptOptions = {
    ...DOUGHNUT_OPTIONS,
    onClick: makeClickHandler(
      report.byReportingDepartment,
      () => buildBaseDateListUrl(filters),
      (item) => `${item.label} — xem danh sách trong khoảng thời gian đã chọn`,
    ),
  };

  const occurrenceOptions = {
    ...DOUGHNUT_OPTIONS,
    onClick: makeClickHandler(
      report.byOccurrenceStatus,
      () => buildBaseDateListUrl(filters),
      (item) => `${item.label} — xem danh sách trong khoảng thời gian đã chọn`,
    ),
  };

  const severityOptions = {
    ...DOUGHNUT_OPTIONS,
    onClick: makeClickHandler(
      report.bySeverity,
      (item) => buildSeverityListUrl(item.key, filters),
      (item) => `Lọc mức độ: ${item.label} — ${item.count} sự cố`,
    ),
  };

  return (
    <div>
      {/* Popover (fixed-position, shared across all charts in this tab) */}
      {popover && <ChartViewListPopover {...popover} onClose={closePopover} />}

      {/* Row 1: Monthly bar chart (full width) */}
      <div className={`${s.grid1} ${s.chartCard}`} style={{ marginBottom: 16 }}>
        <h3>
          <i className="fas fa-chart-bar" /> Số sự cố y khoa theo tháng
          <ClickHint />
        </h3>
        <Bar data={monthBarData} options={monthOptions} />
      </div>

      {/* Row 2: hình thức + khoa báo cáo (SSOT — mọi báo cáo theo reporting department) */}
      <div className={s.grid2} style={{ marginBottom: 16 }}>
        <div className={s.chartCard}>
          <h3><i className="fas fa-tag" /> Hình thức báo cáo<ClickHint /></h3>
          <Doughnut data={toDoughnutData(report.byReportType)} options={reportTypeOptions} />
        </div>
        <div className={s.chartCard}>
          <h3><i className="fas fa-hospital" /> Khoa báo cáo<ClickHint /></h3>
          <Doughnut data={toDoughnutData(report.byReportingDepartment)} options={reportingDeptOptions} />
        </div>
      </div>

      {/* Row 3: 2 doughnuts + horizontal bar */}
      <div className={s.grid3}>
        <div className={s.chartCard}>
          <h3><i className="fas fa-check-circle" /> Tình trạng xảy ra<ClickHint /></h3>
          <Doughnut data={toDoughnutData(report.byOccurrenceStatus)} options={occurrenceOptions} />
        </div>
        <div className={s.chartCard}>
          <h3><i className="fas fa-exclamation-triangle" /> Mức độ nghiêm trọng<ClickHint /></h3>
          <Doughnut data={toDoughnutData(report.bySeverity)} options={severityOptions} />
        </div>
        <div className={s.chartCard}>
          <h3><i className="fas fa-user-injured" /> Đối tượng bị ảnh hưởng<ClickHint /></h3>
          <Bar data={subjectBarData} options={subjectOptions} />
        </div>
      </div>
    </div>
  );
};
