import React, { useEffect, useRef } from 'react';
import { useAppNavigate } from '../../../hooks/useAppNavigate';
import styles from './ChartViewListPopover.module.css';

export interface ChartPopoverState {
  x: number;
  y: number;
  label: string;
  filterHint: string;
  listUrl: string;
}

interface Props extends ChartPopoverState {
  onClose: () => void;
}

/**
 * Fixed-position popover shown when a user clicks a chart element.
 * Appears above the cursor and provides a "Xem danh sách" navigation link.
 */
export const ChartViewListPopover: React.FC<Props> = ({
  x, y, label, filterHint, listUrl, onClose,
}) => {
  const ref         = useRef<HTMLDivElement>(null);
  const appNavigate = useAppNavigate();

  useEffect(() => {
    const onMouseDown = (e: MouseEvent) => {
      if (ref.current && ref.current.contains(e.target as Node)) return;
      // Let chart canvas clicks be handled by Chart.js onClick (which will update/close popover)
      if ((e.target as HTMLElement)?.tagName === 'CANVAS') return;
      onClose();
    };
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('mousedown', onMouseDown);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onMouseDown);
      document.removeEventListener('keydown', onKey);
    };
  }, [onClose]);

  const handleViewList = (e: React.MouseEvent) => {
    e.stopPropagation();
    appNavigate(listUrl);
    onClose();
  };

  // Prevent popover from going off the right or left edge of the viewport
  const safeLeft = Math.max(110, Math.min(x, window.innerWidth - 110));
  // If too close to top, show below cursor instead of above
  const showAbove = y > 130;

  return (
    <div
      ref={ref}
      className={`${styles.popover} ${showAbove ? styles.above : styles.below}`}
      style={{ left: safeLeft, top: showAbove ? y - 8 : y + 8 }}
    >
      <button className={styles.closeBtn} onClick={onClose} title="Đóng">
        <i className="fas fa-times" />
      </button>
      <div className={styles.label}>{label}</div>
      {filterHint && <div className={styles.hint}>{filterHint}</div>}
      <button className={styles.viewBtn} onClick={handleViewList}>
        <i className="fas fa-list" />
        Xem danh sách
      </button>
    </div>
  );
};
