import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { MedicalIncidentReportFilters } from '../../../models/MedicalIncident';
import { useFormOptions } from '../../../hooks/useFormOptions';
import { currentYearDateRange, useReportPeriodFilter } from '../../../hooks/useReportPeriodFilter';
import styles from './MedicalIncidentReportFilters.module.css';
import {
  LinErpListFilterBar,
  LinReportPeriodSelectorFields,
  SearchTextInput,
  Select,
  SelectOption,
} from '@linm-soft-org/linm-web-common-components';

const TEST_ID_PREFIX = 'medical-incident-report';

interface Props {
  filters: MedicalIncidentReportFilters;
  onSearch: (f: MedicalIncidentReportFilters) => void;
  onClear: () => void;
  loading?: boolean;
}

export const MedicalIncidentReportFiltersBar: React.FC<Props> = ({
  filters,
  onSearch,
  onClear,
  loading = false,
}) => {
  const [draft, setDraft] = useState<MedicalIncidentReportFilters>(filters);
  const { departmentOptions } = useFormOptions('incident-list');

  useEffect(() => {
    setDraft(filters);
  }, [filters]);

  const commitDates = useCallback(
    (dateFrom: string, dateTo: string) => {
      setDraft((prev) => {
        const next = { ...prev, dateFrom, dateTo, year: undefined };
        onSearch({
          ...next,
          reportingDepartmentId: next.reportingDepartmentId || undefined,
          includeDraft: next.includeDraft || undefined,
        });
        return next;
      });
    },
    [onSearch],
  );

  const period = useReportPeriodFilter(commitDates, 'year');

  const allDeptOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả khoa báo cáo' }, ...departmentOptions],
    [departmentOptions],
  );

  const hasActiveFilters = !!(
    draft.search ||
    draft.reportingDepartmentId ||
    draft.includeDraft ||
    period.viewMode !== 'year'
  );

  const handleSearch = () => {
    onSearch({
      ...draft,
      search: draft.search?.trim() || undefined,
      dateFrom: period.fromDate || draft.dateFrom,
      dateTo: period.toDate || draft.dateTo,
      reportingDepartmentId: draft.reportingDepartmentId || undefined,
      includeDraft: draft.includeDraft || undefined,
    });
  };

  const handleClear = () => {
    period.resetToDefaultYear();
    const year = currentYearDateRange();
    setDraft({ dateFrom: year.dateFrom, dateTo: year.dateTo });
    onClear();
  };

  const periodShared = {
    testIdPrefix: TEST_ID_PREFIX,
    labels: period.periodLabels,
    viewMode: period.viewMode,
    month: period.month,
    year: period.year,
    quarter: period.quarter,
    yearOptions: period.yearOptions,
    onViewModeChange: period.handleViewModeChange,
    onMonthChange: period.setMonth,
    onYearChange: period.setYear,
    onQuarterChange: period.setQuarter,
  };

  return (
    <LinErpListFilterBar
      testIdPrefix={TEST_ID_PREFIX}
      fromDate={period.fromDate}
      toDate={period.toDate}
      onDateChange={period.handleDateRangeChange}
      onSearch={handleSearch}
      loading={loading}
      leading={(
        <>
          <div data-testid={`${TEST_ID_PREFIX}-field-search`}>
            <SearchTextInput
              placeholder="Tìm kiếm sự cố..."
              value={draft.search ?? ''}
              onChange={(search) => setDraft((prev) => ({ ...prev, search }))}
              onSearch={handleSearch}
              testId={`${TEST_ID_PREFIX}-search-text`}
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-reportingDepartment`}>
            <Select
              label="Khoa báo cáo"
              options={allDeptOptions}
              value={draft.reportingDepartmentId ?? ''}
              onChange={(e) => {
                const next = {
                  ...draft,
                  dateFrom: period.fromDate,
                  dateTo: period.toDate,
                  reportingDepartmentId: e.target.value || undefined,
                };
                setDraft(next);
                onSearch({
                  ...next,
                  reportingDepartmentId: next.reportingDepartmentId || undefined,
                  includeDraft: next.includeDraft || undefined,
                });
              }}
              size="small"
            />
          </div>
          <label className={styles.draftToggle}>
            <input
              type="checkbox"
              checked={!!draft.includeDraft}
              onChange={(e) =>
                setDraft((prev) => ({ ...prev, includeDraft: e.target.checked }))
              }
            />
            <span>Cả bản nháp</span>
          </label>
          {hasActiveFilters && (
            <button
              className={styles.clearFiltersButton}
              onClick={handleClear}
              type="button"
              title="Xóa bộ lọc"
            >
              <i className="fas fa-times-circle" />
              <span>Xóa bộ lọc</span>
            </button>
          )}
        </>
      )}
      dateLeading={<LinReportPeriodSelectorFields {...periodShared} />}
    />
  );
};
